"""Fault-injected refusal contracts for admission-owner integration; no guards added."""
from pathlib import Path
import sys,json,hashlib
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'tests'))
from test_mobile_rendering import html
from playwright.sync_api import sync_playwright
source=(ROOT/'assets/game.js').read_text()
probe=r'''
window.__capacityContracts={
 reset:()=>{__townTest.reset('settlement',42);},
 balances:()=>({day:G.day,treasury:G.treasury,region:G.region,total:totalMoney(),rng:rngState,people:G.people.length,households:G.households.length,firms:G.firms.length,buildings:G.buildings.length,projects:G.projects.length,nextId:G.nextId}),
 slot:kind=>{for(let y=2;y<T-2;y++)for(let x=2;x<T-2;x++)if(canPlace(x,y,true,kind))return {x,y};throw Error('No fixture site '+kind);},
 constructRefusal:()=>{const s=__capacityContracts;s.reset();const pos=s.slot('grocer'),before=s.balances(),create=createFirm;let calls=0,error='';try{createFirm=()=>{calls++;return null;};construct('grocer',pos.x,pos.y);}catch(e){error=e.message;}finally{createFirm=create;}return {before,after:s.balances(),calls,error,kind:'Hypothetical inner creator null refusal, public construct command'};},
 completionRefusal:()=>{const s=__capacityContracts;s.reset();const pos=s.slot('grocer'),b=startDevelopmentProject('firm',pos,70000,1,{firmKind:'grocer',capital:12000});if(!b)throw Error('Fixture project rejected');const before=s.balances(),create=createFirm,work=constructionWork;let calls=0,error='';try{createFirm=()=>{calls++;return null;};constructionWork=()=>true;completeDevelopmentProjects();}catch(e){error=e.message;}finally{createFirm=create;constructionWork=work;}return {before,after:s.balances(),calls,error,buildingKind:b.kind,kind:'Hypothetical creator null at completion; construction work isolated'};},
 arrivalDeferral:()=>{const s=__capacityContracts;s.reset();const pos=s.slot('home'),b={id:G.nextId++,kind:'home',...pos,value:48000,condition:100,owner:-1,firm:-1,hh:-1,municipalRehousing:true};G.buildings.push(b);G.homes.push(b.id);invalidateRoads(false);G.day=2;const before=s.balances(),assessment=migrationAssessment,recordBefore=migrationReport().length;let result;try{migrationAssessment=()=>({eligible:false,reasons:['Controlled downstream refusal']});result=addHouseholdAt(b,1700);}finally{migrationAssessment=assessment;}return {before,after:s.balances(),returnedNull:result===null,migrationRecordBefore:recordBefore,derivedMigrationRecords:migrationReport().slice(),migrationReportIsPersistent:false,kind:'Actual addHouseholdAt deferred assessment; RNG already generated profiles'};},
 creditDecline:()=>{const s=__capacityContracts;s.reset();G.loans=Array.from({length:10000},(_,i)=>({id:i+1,bankId:0,ownerType:'household',ownerId:0,original:1,balance:1,rate:.1,term:360,created:1,arrears:0,status:'default',paid:0}));G.nextLoanId=10000;const before=s.balances(),hadDecision=Object.hasOwn(G.households[0],'creditDecision'),result=bankLoan('household',0,1000);return {before,after:s.balances(),returnedNull:result===null,hadDecision,decision:G.households[0].creditDecision,nextLoanId:G.nextLoanId,kind:'Actual retained debt ledger cap decline; synthetic protected obligations'};},
 tickRefusal:()=>{const s=__capacityContracts;s.reset();const before=s.balances(),economy=dailyEconomy,persist=persistSnapshot,ready=saveStoreReady,busy=simulationBusy;let error='',writes=[];try{saveStoreReady=true;simulationBusy=false;persistSnapshot=payload=>{writes.push({day:JSON.parse(payload).day,bytes:new Blob([payload]).size});return Promise.resolve(true);};dailyEconomy=()=>{save();throw Error('Controlled capacity refusal after mid-day save');};tick();}catch(e){error=e.message;}finally{dailyEconomy=economy;persistSnapshot=persist;saveStoreReady=ready;simulationBusy=busy;}return {before,after:s.balances(),error,writes,kind:'Fault-injected downstream refusal; frame-equivalent simulationBusy=false and persistence spy'};},
 prepareEvent:()=>{const s=__capacityContracts;s.reset();const before=s.balances();window.__refusalEventBefore=before;showCustomEvent('CAPACITY CONTRACT PROBE','Controlled refusal','A deliberately refused mutation for integration review.',[{title:'Attempt refused purchase',cost:1000,apply:()=>{throw Error('Controlled capacity refusal');}}]);return before;},
 eventResult:()=>({before:window.__refusalEventBefore,after:__capacityContracts.balances(),journal:fromEnd(G.journal),pendingEvent:!!pendingEvent})
};
'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click()
 result={name:p.evaluate('__capacityContracts.'+name+'()') for name in ['constructRefusal','completionRefusal','arrivalDeferral','creditDecline','tickRefusal']};p.evaluate('__capacityContracts.prepareEvent()');p.locator('#eventChoices button').first.click();result['eventRefusal']=p.evaluate('__capacityContracts.eventResult()');b.close()
assert result['constructRefusal']['calls']==1 and result['constructRefusal']['after']['total']<result['constructRefusal']['before']['total'], 'Construct refusal probe did not reach unsafe caller'
assert result['completionRefusal']['calls']==1 and result['completionRefusal']['after']['projects']==result['completionRefusal']['before']['projects']-1, 'Completion refusal probe missed removal'
assert result['arrivalDeferral']['returnedNull'] and result['arrivalDeferral']['before']['rng']!=result['arrivalDeferral']['after']['rng'], 'Arrival RNG probe missed profile generation'
assert result['creditDecline']['returnedNull'] and result['creditDecline']['decision']['approved'] is False, 'Credit decline probe missed persistent decision'
assert len(result['tickRefusal']['writes'])==1 and result['tickRefusal']['writes'][0]['day']==result['tickRefusal']['before']['day']+1, 'Tick side-effect probe missed partial-day write'
assert result['eventRefusal']['after']['treasury']==result['eventRefusal']['before']['treasury']-1000 and result['eventRefusal']['pendingEvent'] is False, 'Council refusal probe missed caught charge'
out={'base':'6c02aadf293513d022f7a3868b52abe050202880','source_sha256':hashlib.sha256(source.encode()).hexdigest(),'hostChromium':True,'physicalAndroid':False,'faultInjectionOnly':True,'guardsImplemented':False,'result':result};(ROOT/'reports/capacity-refusal-contracts.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
